/**
 * Если размер пакета для таймеров не определён
 */
#ifndef AWH_BATCH_SIZE_INTERNAL_TIMER
	/**
	 * @brief Устанавливаем размер пакета для таймеров в 256
	 *
	 */
	#define AWH_BATCH_SIZE_INTERNAL_TIMER 0x100
#endif

/**
 * Если количество идентификаторов таймаутов на одно событие не определено
 */
#ifndef AWH_COUNT_IDS_INTERNAL_TIMER
	/**
	 * @brief Устанавливаем количество идентификаторов таймаутов на одно событие в 8
	 *
	 * @note Этим значением задаётся вторая размерность таблицы слотов сложной
	 *       структуры дедлайнов, и оно должно покрывать все идентификаторы
	 *       таймаутов: чтение, запись, подключение, переподключение, ограничение
	 *       полосы на чтение и запись и пользовательский таймер - семь штук.
	 *       Раньше размерность задавалась размером пакета в 256, то есть таблица
	 *       на каждую тысячу событий занимала мебибайт при полезных двадцати восьми
	 *       октетах на событие. Пользовательские таймеры проходят через ту же
	 *       таблицу, поэтому расход стал заметен: тридцать два кибибайта на чанк
	 *       вместо мебибайта
	 *
	 */
	#define AWH_COUNT_IDS_INTERNAL_TIMER 0x08
#endif

/**
 * Если количество обработанных таймеров не определено
 */
#ifndef AWH_COUNT_PROCESSED_INTERNAL_TIMER
	/**
	 * @brief Устанавливаем количество обработанных таймеров в 256, для предотвращения бесконечного цикла
	 *
	 */
	#define AWH_COUNT_PROCESSED_INTERNAL_TIMER 0x100
#endif

/**
 * Если размер кучи для таймеров не определён
 */
#ifndef AWH_HEAP_SIZE_INTERNAL_TIMER
	/**
	 * @brief Устанавливаем размер кучи для таймеров в 50 000 элементов
	 *
	 * @note Достаточно для 12.5 млн таймеров при 256 таймерах на eid
	 *
	 */
	#define AWH_HEAP_SIZE_INTERNAL_TIMER 0xC350
#endif

/**
 * Если размер чанка для таймеров не определён
 */
#ifndef AWH_CHUNK_EIDS_INTERNAL_TIMER
	/**
	 * @brief Устанавливаем размер чанка в 1024 eid × 256 таймеров/ид = 1 МБ на чанк
	 *
	 * @note При необходимости можно увеличить до 4096 для лучшей кэш-локальности при >500k таймеров
	 *
	 */
	#define AWH_CHUNK_EIDS_INTERNAL_TIMER 0x400
#endif

/**
 * Если порог "незначительного" сдвига дедлайна не определён
 */
#ifndef AWH_SIFT_THRESHOLD_MS_INTERNAL_TIMER
	/**
	 * @brief Порог "незначительного" сдвига дедлайна (в мс)
	 *
	 * @note Если обновление таймера сдвинуло дедлайн меньше чем на это значение —
	 *       перестройка кучи пропускается (погрешность планировщика всё равно съест)
	 *
	 */
	#define AWH_SIFT_THRESHOLD_MS_INTERNAL_TIMER 0x02
#endif

/**
 * Если начальный размер массива опрашиваемых событий не установлен
 */
#ifndef AWH_MAX_POLL_EVENTS_COUNT
	/**
	 * @brief Устанавливаем начальный размер массива опрашиваемых событий (64)
	 *
	 */
	#define AWH_MAX_POLL_EVENTS_COUNT 0x40
#endif

/**
 * Если верхний предел роста массива опрашиваемых событий не установлен
 */
#ifndef AWH_MAX_POLL_EVENTS_LIMIT
	/**
	 * @brief Устанавливаем верхний предел роста массива опрашиваемых событий (4096)
	 *
	 * @note Массив растёт по нагрузке, но не безгранично: за один опрос имеет смысл
	 *       забирать столько событий, сколько цикл успеет разобрать, не откладывая
	 *       надолго ни взвод дедлайнов, ни отправку накопленных изменений. Остаток
	 *       никуда не денется - дескрипторы остались готовыми, и ближайший опрос
	 *       заберёт их не ожидая
	 *
	 * @note У libevent и libev потолка нет вовсе, массив удваивается до упора и
	 *       ограничен только переполнением целого. libuv поступает наоборот: держит
	 *       массив в 1024 записи и, получив его заполненным, тут же опрашивает ядро
	 *       повторно с нулевым ожиданием. Выбран средний путь: рост до предела, за
	 *       которым разбор одной пачки начинает задерживать всё остальное
	 *
	 */
	#define AWH_MAX_POLL_EVENTS_LIMIT 0x1000
#endif

/**
 * Если длительность затишья, по которой массив событий ужимается, не установлена
 */
#ifndef AWH_POLL_EVENTS_IDLE_ROUNDS
	/**
	 * @brief Устанавливаем длительность затишья для сжатия массива событий (1024 опроса)
	 *
	 */
	#define AWH_POLL_EVENTS_IDLE_ROUNDS 0x400
#endif

/**
 * Если максимальный размер буфера на чтение данных не определён
 */
#ifndef AWH_EVENT_MAX_BUFFER_SIZE
	/**
	 * @brief Устанавливаем максимальный размер буфера на чтение данных в 64 КБ
	 *
	 */
	#define AWH_EVENT_MAX_BUFFER_SIZE 0x10000
#endif

/**
 * Если максимальное время ожидания получения данных не определено
 */
#ifndef AWH_EVENT_MAX_LOOP_WAIT
	/**
	 * @brief Устанавливаем максимальное время ожидания получения данных в 500 мкс
	 *
	 */
	#define AWH_EVENT_MAX_LOOP_WAIT 0x7A120
#endif

/**
 * Если размер MTU для UDP сообщений в IPv4 не определён
 */
#ifndef AWH_MTU_UDP_IPV4_PAYLOAD_SIZE
	/**
	 * @brief Устанавливаем рекомендуемый размер UDP-полезной нагрузки для IPv4 в 1400 байт
	 *        1400 = 1500 (Ethernet MTU) - 20 (IPv4) - 8 (UDP) - 72 (запас на инкапсуляцию)
	 *
	 * @note Для работы с DTLS лучше заложить 1454 байта, но для UDP достаточно 1400 байт.
	 *
	 * @note 1500 - 20 (IP) - 8 (UDP) = 1472 максимум без фрагментации
	 *       Запас 72 байта на возможную инкапсуляцию (туннели, провайдерские заголовки)
	 *       Больше → фрагментация → потеря пакетов
	 *
	 */
	#define AWH_MTU_UDP_IPV4_PAYLOAD_SIZE 0x578
#endif

/**
 * Если размер MTU для UDP сообщений в IPv6 не определён
 */
#ifndef AWH_MTU_UDP_IPV6_PAYLOAD_SIZE
	/**
	 * @brief Устанавливаем рекомендуемый размер UDP-полезной нагрузки для IPv6 в 1380 байт
	 *        1380 = 1500 (Ethernet MTU) - 40 (IPv6) - 8 (UDP) - 72 (запас на инкапсуляцию)
	 *
	 * @note 1500 - 40 (IPv6) - 8 (UDP) = 1452 максимум без фрагментации
	 *       Запас 72 байта на инкапсуляцию (туннели часто используют двойную инкапсуляцию)
	 *       IPv6 не фрагментирует на маршрутизаторах → фрагментированные пакеты отбрасываются
	 *
	 */
	#define AWH_MTU_UDP_IPV6_PAYLOAD_SIZE 0x564
#endif

/**
 * Если окно всплеска ограничения пропускной способности не определено
 */
#ifndef AWH_BANDWIDTH_BURST_WINDOW
	/**
	 * @brief Устанавливаем окно всплеска ограничения пропускной способности в 10 миллисекунд
	 *
	 * @note Окно задаёт две величины разом: сколько токенов ведро накапливает
	 *       за простой и сколько октетов отдаётся за одну операцию. Десять
	 *       миллисекунд - тот же запас, что ведро приёма держало и прежде
	 *
	 */
	#define AWH_BANDWIDTH_BURST_WINDOW 0.01
#endif

/**
 * Если размер MTU для TCP сообщений в IPv4 не определён
 */
#ifndef AWH_MTU_TCP_IPV4_PAYLOAD_SIZE
	/**
	 * @brief Устанавливаем рекомендуемый размер TCP-полезной нагрузки для IPv4 в 1440 байт
	 *        1440 = 1500 (Ethernet MTU) - 20 (IPv4) - 20 (TCP) - 20 (запас на опции/инкапсуляцию)
	 *
	 * @note Ядро разобьёт на сегменты по MSS (~1448-1460)
	 *       Размер кратен MSS → минимум «хвостовых» мелких сегментов
	 *       Достаточно большой для плавности, достаточно маленький для точности ограничения
	 *
	 */
	#define AWH_MTU_TCP_IPV4_PAYLOAD_SIZE 0x5A0
#endif

/**
 * Если размер MTU для TCP сообщений в IPv6 не определён
 */
#ifndef AWH_MTU_TCP_IPV6_PAYLOAD_SIZE
	/**
	 * @brief Устанавливаем рекомендуемый размер TCP-полезной нагрузки для IPv6 в 1420 байт
	 *        1420 = 1500 (Ethernet MTU) - 40 (IPv6) - 20 (TCP) - 20 (запас на опции/инкапсуляцию)
	 *
	 * @note Учёт 40-байтного заголовка IPv6
	 *       Кратно эффективному MSS для IPv6 (~1420-1440)
	 *       Аналогично IPv4 — баланс плавности и точности
	 *
	 */
	#define AWH_MTU_TCP_IPV6_PAYLOAD_SIZE 0x58C
#endif

