		/**
		 * @brief Функция постановки дедлайна
		 *
		 * @param tm   объект таймера
		 * @param eid  идентификатор события для которого устанавливается таймер
		 * @param flag флаг активации таймера
		 * @param rate режим ограничения скорости события
		 * @param log  объект работы с логами
		 *
		 */
		static void __set__(::io::timeout_t & tm, const event::id_t eid, const flag_t flag, const event::rate_t rate, const log_t * log) noexcept {
			/**
			 * Выполняем перехват ошибок
			 */
			try {
				// Получаем текущее значение времени
				const uint64_t now = ::timer::now();
				/**
				 * Определяем как нужно работать с таймером в зависимости от переданных флагов
				 */
				switch(static_cast <uint8_t> (flag)){
					// Если установлен флаг SIMPLE, таймер устанавливается если ранее не был установлен для данного события
					case static_cast <uint8_t> (flag_t::SIMPLE): {
						// Если время задержки таймаута установлено
						if(tm.delay > 0){
							/**
							 * В зависимости от текущего статуса события создаём новый или обновляем таймер
							 */
							switch(static_cast <uint8_t> (tm.status)){
								// Если таймаут ожидания не активирован ранее
								case static_cast <uint8_t> (event::status_t::NONE):
									// Устанавливаем статус таймаута в ожидание
									tm.status = event::status_t::PENDING;
								// Если таймаут ожидания уже активирован для данного события
								case static_cast <uint8_t> (event::status_t::PENDING): {
									// Вычисляем дедлайн таймера как сумму текущего времени и заданной задержки в миллисекундах
									const uint64_t deadline = (now + static_cast <uint64_t> (tm.delay));
									// Получаем объект чанка для данного идентификатора события
									Chunk * chunk = __get_chunk__(eid);
									// Вычисляем смещение внутри чанка для данного идентификатора события
									const size_t offset = (eid & (AWH_CHUNK_EIDS_INTERNAL_TIMER - 1)); // eid % 1024
									// Получаем индекс таймера в куче для данного идентификатора таймера и смещения внутри чанка
									int32_t & index = chunk->slots[offset][tm.id];
									// Если индекс таймера в куче не равен -1, таймер уже существует, и нам нужно обновить его дедлайн
									if(index != -1){
										// Таймер уже существует: обновляем дедлайн
										Timer & timer = __awh_heap__[index];
										// Сохраняем старый дедлайн для оптимизации перестройки кучи
										const uint64_t old = timer.deadline;
										// Обновляем дедлайн таймера на новый рассчитанный дедлайн
										timer.deadline = deadline;
										/**
										 * Оптимизация:
										 * - Пропускаем перестройку кучи при незначительном сдвиге (погрешность планировщика + syscall всё равно съест разницу ≤2 мс)
										 * - На случай если дедлайн сдвинулся в обе стороны (хотя в реальной жизни это маловероятно), проверяем оба направления
										 */
										// Если дедлайн сдвинут значительно в сторону более раннего времени → поднимаем элемент вверх по куче
										if(deadline < (old - AWH_SIFT_THRESHOLD_MS_INTERNAL_TIMER))
											// Выполняем подъём элемента вверх по куче для восстановления свойства кучи после изменения дедлайна таймера
											__sift_up__(index);
										// Если дедлайн сдвинут значительно в сторону более позднего времени → опускаем элемент вниз по куче
										else if(deadline > (old + AWH_SIFT_THRESHOLD_MS_INTERNAL_TIMER))
											// Выполняем опускание элемента вниз по куче для восстановления свойства кучи после изменения дедлайна таймера
											__sift_down__(index);
										// else: дедлайн сдвинут незначительно → оставляем как есть
									// Если индекс таймера в куче равен -1, таймер не существует, и нам нужно создать новый таймер
									} else {
										// Добавляем новый таймер в кучу с заданным идентификатором таймера
										__awh_heap__.push_back({tm.id, eid, deadline});
										// Получаем индекс нового таймера в куче, который будет использоваться для обновления слота в чанке
										index = static_cast <int32_t> (__awh_heap__.size() - 1);
										// Увеличиваем счётчик активных таймеров в чанке, так-как мы добавили новый таймер
										chunk->count++;
										// Выполняем подъём элемента вверх по куче для восстановления свойства кучи после добавления нового таймера
										__sift_up__(index);
									}
								} break;
							}
						}
					} break;
					// Если установлен флаг FORCED, таймер устанавливается принудительно, даже если ранее был установлен для данного события
					case static_cast <uint8_t> (flag_t::FORCED): {
						// Если время задержки таймаута не установлено
						if(tm.delay == 0)
							// Устанавливаем время задержки таймаута по умолчанию в 1 миллисекунду
							tm.delay = 1;
						// Устанавливаем статус таймаута в ожидание
						tm.status = event::status_t::PENDING;
						// Вычисляем дедлайн таймера как сумму текущего времени и заданной задержки в миллисекундах
						const uint64_t deadline = (now + static_cast <uint64_t> (tm.delay));
						// Получаем объект чанка для данного идентификатора события
						Chunk * chunk = __get_chunk__(eid);
						// Вычисляем смещение внутри чанка для данного идентификатора события
						const size_t offset = (eid & (AWH_CHUNK_EIDS_INTERNAL_TIMER - 1)); // eid % 1024
						// Получаем индекс таймера в куче для данного идентификатора таймера и смещения внутри чанка
						int32_t & index = chunk->slots[offset][tm.id];
						// Если индекс таймера в куче не равен -1, таймер уже существует, и нам нужно обновить его дедлайн
						if(index != -1){
							// Таймер уже существует: обновляем дедлайн
							Timer & timer = __awh_heap__[index];
							// Сохраняем старый дедлайн для оптимизации перестройки кучи
							const uint64_t old = timer.deadline;
							// Обновляем дедлайн таймера на новый рассчитанный дедлайн
							timer.deadline = deadline;
							/**
							 * Оптимизация:
							 * - Пропускаем перестройку кучи при незначительном сдвиге (погрешность планировщика + syscall всё равно съест разницу ≤2 мс)
							 * - На случай если дедлайн сдвинулся в обе стороны (хотя в реальной жизни это маловероятно), проверяем оба направления
							 */
							// Если дедлайн сдвинут значительно в сторону более раннего времени → поднимаем элемент вверх по куче
							if(deadline < (old - AWH_SIFT_THRESHOLD_MS_INTERNAL_TIMER))
								// Выполняем подъём элемента вверх по куче для восстановления свойства кучи после изменения дедлайна таймера
								__sift_up__(index);
							// Если дедлайн сдвинут значительно в сторону более позднего времени → опускаем элемент вниз по куче
							else if(deadline > (old + AWH_SIFT_THRESHOLD_MS_INTERNAL_TIMER))
								// Выполняем опускание элемента вниз по куче для восстановления свойства кучи после изменения дедлайна таймера
								__sift_down__(index);
							// else: дедлайн сдвинут незначительно → оставляем как есть
						// Если индекс таймера в куче равен -1, таймер не существует, и нам нужно создать новый таймер
						} else {
							// Добавляем новый таймер в кучу с заданным идентификатором таймера
							__awh_heap__.push_back({tm.id, eid, deadline});
							// Получаем индекс нового таймера в куче, который будет использоваться для обновления слота в чанке
							index = static_cast <int32_t> (__awh_heap__.size() - 1);
							// Увеличиваем счётчик активных таймеров в чанке, так-как мы добавили новый таймер
							chunk->count++;
							// Выполняем подъём элемента вверх по куче для восстановления свойства кучи после добавления нового таймера
							__sift_up__(index);
						}
					} break;
				}
			/**
			 * Если возникает ошибка
			 */
			} catch(const exception & error) {
				/**
				 * Если включён режим отладки
				 */
				#if DEBUG_MODE
					// Записываем ошибку в лог
					log->debug("%s", __PRETTY_FUNCTION__, make_tuple(eid, static_cast <uint32_t> (tm.delay), static_cast <uint16_t> (flag), static_cast <uint16_t> (rate)), log_t::flag_t::CRITICAL, error.what());
				/**
				 * Если режим отладки не включён
				 */
				#else
					// Записываем ошибку в лог
					log->print("%s", log_t::flag_t::CRITICAL, error.what());
				#endif
			}
		}

		/**
		 * @brief Функция установки таймера
		 *
		 * @details Простой таймер без заданной задержки не ставится, и отсев таких
		 *          вызовов вынесен сюда, на порог, пригодный для встраивания. Постановка
		 *          дедлайна зовётся на каждое чтение и на каждую запись, а таймаут
		 *          событию задан далеко не всегда: на обмене короткими сообщениями через
		 *          порог проходило два вызова на обмен, и оба выходили первой же
		 *          проверкой, не сделав ничего. Невстраиваемый вызов с блоком перехвата
		 *          ошибок ради этой проверки обходился дороже всей отправки вне ядра.
		 *
		 * @param tm   объект таймера
		 * @param eid  идентификатор события для которого устанавливается таймер
		 * @param flag флаг активации таймера
		 * @param rate режим ограничения скорости события
		 * @param log  объект работы с логами
		 *
		 */
		static inline void set(::io::timeout_t & tm, const event::id_t eid, const flag_t flag, const event::rate_t rate, const log_t * log) noexcept {
			// Если простому таймеру задержка не задана, ставить нечего
			if((flag == flag_t::SIMPLE) && (tm.delay == 0))
				// Выходим из функции, так-как дедлайн не нужен
				return;
			// Выполняем постановку дедлайна
			__set__(tm, eid, flag, rate, log);
		}

		/**
		 * @brief Функция установки одного таймера
		 *
		 * @param rec  объект записи параметров для установки таймера
		 * @param eid  идентификатор события для которого устанавливается таймер
		 * @param rate режим ограничения скорости события
		 * @param log  объект работы с логами
		 *
		 */
		static void set(record_t rec, const event::id_t eid, const event::rate_t rate, const log_t * log) noexcept {
			// Устанавливаем таймер на основе переданных параметров
			set(rec.tm, eid, rec.flag, rate, log);
			/**
			 * Перезапускаем таймер ядра операционной системы на основе ближайшего срока
			 * истечения таймера в приоритетной очереди. Вызов безусловный: решение о том,
			 * нужно ли вообще обращаться к ядру, принимается внутри по запомненному сроку
			 * истечения, на который ядро взведено сейчас. Прежняя проверка здесь пыталась
			 * угадать это по тому, стал ли поставленный таймер ближайшим, и промахивалась
			 * ровно тогда, когда ядро не было взведено вовсе
			 */
			__rearm__(rate, log);
		}

