													// Если нам нужно попытаться отправить позже
													case EINTR:
													case ENOBUFS:
													case ENOMEM:
													case EAGAIN:
														// Устанавливаем идентификатор полученной ошибки
														error = event::error_t::EVENT_FAIL;
													break;
													// Если мы получили другую непонятную ошибку
