							if((isSetup = this->_eth.socket.switchOption(fd, i->second->state.family, net::socket_mode_t::DISABLED, event::options::REUSE_PORT)))
								// Снимаем опцию события
								i->second->state.options &= ~event::options::REUSE_PORT;
